def parse_dsn(dsn: str) -> dict:
    prefix = "postgresql://"
    if not dsn.startswith(prefix):
        raise ValueError("DSN must start with postgresql://")

    rest = dsn[len(prefix):]

    # 分离用户信息和主机部分
    at_index = rest.rfind("@")
    if at_index == -1:
        user_info = ""
        host_db = rest
    else:
        user_info = rest[:at_index]
        host_db = rest[at_index + 1:]

    # 解析用户名和密码
    user = ""
    password = ""
    if user_info:
        if ":" in user_info:
            user, password = user_info.split(":", 1)
        else:
            user = user_info

    # 分离主机和数据库名
    if "/" in host_db:
        host_port, dbname = host_db.split("/", 1)
    else:
        host_port, dbname = host_db, ""

    # 解析主机和端口
    if host_port.startswith("["):
        # IPv6 地址，例如 [::1]:5432
        closing_bracket = host_port.find("]")
        if closing_bracket == -1:
            raise ValueError("Invalid IPv6 host in DSN")
        host = host_port[1:closing_bracket]
        remain = host_port[closing_bracket + 1:]
        if remain.startswith(":"):
            port = int(remain[1:])
        else:
            port = 5432
    else:
        if ":" in host_port:
            host, port_str = host_port.rsplit(":", 1)
            try:
                port = int(port_str)
            except ValueError:
                raise ValueError("Invalid port in DSN")
        else:
            host = host_port
            port = 5432

    return {
        "user": user,
        "password": password,
        "host": host,
        "port": port,
        "dbname": dbname,
    }

